# -*- coding: utf-8 -*-
"""어라운드툴 명소 안내 (2026-11-12 대표 지시: K링크에서 명소를 누르면 어라운드툴이 만든 정보가 보기 좋게 나오게)

- 키는 K링크 장소 id (scripts/klink/build/places.json). 사이트 빌드가
  ① 그 지역 여행 가이드(travel-<지역>.html)에 '명소 안내' 카드로 넣고(#spot-<id>),
  ② klink/around.json 의 spots 로 내보내 K링크 상세 화면이 그대로 보여 준다.
- 사실·수치는 공식 안내나 관광 정보로 확인한 것만 쓰고 src 에 출처, checked 에 확인일을 적는다.
  확인 못 한 운영 시간·요금은 '가게마다 다름', '방문 전 확인'처럼 쓰고 숫자를 지어내지 않는다.
- 아직 안내가 없는 K링크 장소는 상세 화면에 '명소 안내 준비 중'으로 보이고, 빌드가 klink/build/spots_todo.json 에 목록을 남긴다.
  아침 회의가 여행 10개를 고를 때 이 목록에서 먼저 채운다(결정기록 2026-11-12).
- photo: scripts/photos.json 의 사진 이름(없으면 None). 사진 후보는 photo_queries.json 의 'k-<지역>-<이름>' 검색어로 받는다.

필드: one(두 줄 요약) · see[(이름, 설명)] 2~3개 · facts{hours, fee, stay, when, access} · tips[] · src[(이름, url)] · checked · photo
"""

